def remove_duplicates(input_list):
    seen = set()
    result = []
    for item in input_list:
        if item not in seen:
            seen.add(item)
            if len(seen) > 1:
                result.append(item)
            seen.add(item)
    return ''.join([x for x in reversed(result)])
```

